WITH flattened_attrs AS (SELECT id, service, host, log_ts, latency_ms, status_code, context, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text, SHIFTRIGHT(status_code, 2) AS status_code_high FROM app_logs WHERE host = 'h1') SELECT CASE WHEN status_code >= 388 THEN 'PREMIUM' ELSE 'STANDARD' END AS status_code_tier, BIT_OR(latency_ms) AS latency_ms_bit_or, ROUND(AVG(status_code_high), 2) AS avg_status_code_high, COUNT(CASE WHEN service = 'search' THEN 1 END) AS search_count, APPROX_PERCENTILE(latency_ms, ARRAY(0.25, 0.5, 0.75)) AS latency_ms_quartiles FROM flattened_attrs GROUP BY 1;
